property.value:
{#
 # Connection profile for dbt. Rendered by Ambari from dbt-env; edit the template in the service
 # configuration rather than this file, because the file is rewritten on every configure.
 #}
{% if not dbt_host %}
# No host is configured for this service, so there is nothing to connect to yet and no profile is
# written. dbt itself works: `dbt --version`, `dbt compile`, `dbt parse`.
#
# Set the host in the service configuration, or write the profile you need into this template.
{% else %}
{{dbt_profile_name}}:
  target: {{dbt_target}}
  outputs:
    {{dbt_target}}:
{% if dbt_adapter_type == 'trino' %}
      type: trino
      method: {{dbt_auth_method}}
      host: {{dbt_host}}
      port: {{dbt_port}}
      database: {{dbt_database}}
      schema: {{dbt_schema}}
      threads: {{dbt_threads}}
      timezone: UTC
      retries: 3
      user: {{dbt_connection_user}}
{% if dbt_auth_method == 'none' %}
      http_scheme: {{dbt_http_scheme}}
{% endif %}
{% if dbt_auth_method == 'ldap' %}
      password: {{dbt_password}}
{% endif %}
{% if dbt_auth_method == 'jwt' %}
      jwt_token: {{dbt_jwt_token}}
{% endif %}
{% if dbt_auth_method == 'kerberos' %}
      {# No keytab here on purpose: on a secured cluster people run dbt as themselves after
         kinit, and dbt uses the ticket in their cache. A headless keytab would make every
         transformation look like one shared identity in the engine's audit log. #}
      service_name: {{dbt_kerberos_service_name}}
      mutual_authentication: false
{% endif %}
{% elif dbt_adapter_type == 'spark' %}
      {# Hive is reached this way too: HiveServer2 speaks the same thrift protocol. #}
      type: spark
      method: {{dbt_spark_method}}
      host: {{dbt_host}}
      port: {{dbt_port}}
      schema: {{dbt_schema}}
      threads: {{dbt_threads}}
      user: {{dbt_connection_user}}
{% if dbt_auth_method == 'kerberos' %}
      auth: KERBEROS
      kerberos_service_name: {{dbt_kerberos_service_name}}
{% endif %}
{% if dbt_auth_method == 'ldap' %}
      password: {{dbt_password}}
{% endif %}
{% elif dbt_adapter_type == 'impala' %}
      type: impala
      host: {{dbt_host}}
      port: {{dbt_port}}
      dbname: {{dbt_database}}
      schema: {{dbt_schema}}
      threads: {{dbt_threads}}
{% if dbt_auth_method == 'kerberos' %}
      auth_type: kerberos
      kerberos_service_name: {{dbt_kerberos_service_name}}
      use_http_transport: false
      use_ssl: true
{% elif dbt_auth_method == 'ldap' %}
      auth_type: ldap
      username: {{dbt_connection_user}}
      password: {{dbt_password}}
      use_ssl: true
{% else %}
      auth_type: insecure
{% endif %}
{% elif dbt_adapter_type == 'postgres' %}
      type: postgres
      host: {{dbt_host}}
      port: {{dbt_port}}
      dbname: {{dbt_database}}
      schema: {{dbt_schema}}
      threads: {{dbt_threads}}
      user: {{dbt_connection_user}}
      password: {{dbt_password}}
{% else %}
      {# Any other adapter in the package: fill in what it needs. The fields below are the ones
         nearly every dbt adapter takes; the rest belong in this template. #}
      type: {{dbt_adapter_type}}
      host: {{dbt_host}}
      port: {{dbt_port}}
      schema: {{dbt_schema}}
      threads: {{dbt_threads}}
      user: {{dbt_connection_user}}
{% endif %}
{% if dbt_ssl_verify %}
      cert: {{dbt_ssl_verify}}
{% endif %}
{% endif %}
